--
-- Name: auth_events_deny_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_events_deny_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' AND current_setting('mindforge.purge_auth_events', true) = 'on' THEN
        RETURN OLD;
    END IF;
    RAISE EXCEPTION 'auth_events is append-only';
END;
$$;


--
-- Name: course_modules_lock_section(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.course_modules_lock_section() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext(NEW.section_id::text));
  IF NEW.position IS NULL THEN
    SELECT COALESCE(MAX(position) + 1, 0) INTO NEW.position
      FROM course_modules WHERE section_id = NEW.section_id AND deleted_at IS NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_last_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_last_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF (OLD.role = 'owner' AND (NEW.status <> 'active' OR NEW.role <> 'owner')) THEN
      IF (SELECT COUNT(*) FROM org_members
          WHERE org_id = OLD.org_id AND role = 'owner' AND status = 'active' AND id <> OLD.id) = 0 THEN
        RAISE EXCEPTION 'cannot remove the last active owner of an organization';
      END IF;
    END IF;
  ELSIF TG_OP = 'DELETE' THEN
    IF OLD.role = 'owner' AND OLD.status = 'active' THEN
      IF (SELECT COUNT(*) FROM org_members
          WHERE org_id = OLD.org_id AND role = 'owner' AND status = 'active' AND id <> OLD.id) = 0 THEN
        RAISE EXCEPTION 'cannot remove the last active owner of an organization';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_slug_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_slug_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.status = 'active' AND NEW.slug <> OLD.slug THEN
    RAISE EXCEPTION 'org slug cannot be changed after activation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enroll_batch_members_in_course(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enroll_batch_members_in_course() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO enrollments (user_id, course_id, batch_id, enrolled_by)
  SELECT bm.user_id, NEW.course_id, NEW.batch_id, NEW.assigned_by
  FROM batch_members bm
  WHERE bm.batch_id = NEW.batch_id
  ON CONFLICT (user_id, course_id) DO NOTHING;
  RETURN NEW;
END;
$$;


--
-- Name: fn_check_user_role_tenant_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_check_user_role_tenant_scope() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  role_org_id UUID;
BEGIN
  SELECT org_id INTO role_org_id FROM roles WHERE id = NEW.role_id;
  IF role_org_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF role_org_id IS DISTINCT FROM NEW.org_id THEN
    RAISE EXCEPTION
      'Org-scope violation: role % belongs to org % but assignment targets org %.',
      NEW.role_id, role_org_id, NEW.org_id
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;


