    CONSTRAINT lab_definitions_lab_type_check CHECK ((lab_type = ANY (ARRAY['terminal'::text, 'code'::text, 'playground'::text, 'guided'::text, 'sandbox'::text, 'debug'::text]))),
    CONSTRAINT lab_definitions_language_check CHECK ((language = ANY (ARRAY['javascript'::text, 'typescript'::text, 'python'::text, 'go'::text]))),
