    merge_request_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT work_item_reviews_check CHECK (((target = 'doc'::text) = (wiki_version IS NOT NULL))),
    CONSTRAINT work_item_reviews_check1 CHECK (((target = 'code'::text) OR (merge_request_id IS NULL))),
    CONSTRAINT work_item_reviews_check2 CHECK (((verdict <> 'changes_requested'::text) OR (comment IS NOT NULL))),
    CONSTRAINT work_item_reviews_comment_check CHECK (((comment IS NULL) OR (char_length(comment) <= 10000))),
    CONSTRAINT work_item_reviews_target_check CHECK ((target = ANY (ARRAY['doc'::text, 'code'::text]))),
    CONSTRAINT work_item_reviews_verdict_check CHECK ((verdict = ANY (ARRAY['approved'::text, 'changes_requested'::text, 'commented'::text]))),
    CONSTRAINT work_item_reviews_wiki_version_check CHECK (((wiki_version IS NULL) OR (wiki_version >= 1)))
);


--
-- Name: work_item_time_logs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.work_item_time_logs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    project_id uuid NOT NULL,
    item_id uuid NOT NULL,
    user_id uuid,
    minutes integer NOT NULL,
    note text,
    logged_on date NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT work_item_time_logs_minutes_check CHECK (((minutes >= 1) AND (minutes <= 720))),
    CONSTRAINT work_item_time_logs_note_check CHECK (((note IS NULL) OR (char_length(note) <= 1000)))
);


--
-- Name: work_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.work_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    project_id uuid NOT NULL,
    key_num integer NOT NULL,
    type text NOT NULL,
    parent_id uuid,
    epic_id uuid,
    feature_id uuid,
    track_id uuid,
    title text NOT NULL,
    description text,
    status text DEFAULT 'todo'::text NOT NULL,
    priority text DEFAULT 'medium'::text NOT NULL,
    severity text,
    is_regression boolean DEFAULT false NOT NULL,
    estimate_minutes integer,
    doc_wiki_page_id uuid,
    doc_status text,
    approved_doc_version integer,
    spec_changed_at timestamp with time zone,
    blocked_reason text,
    reopen_count integer DEFAULT 0 NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    due_at timestamp with time zone,
    created_by uuid,
    archived_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    release_id uuid,
    sprint_id uuid,
    CONSTRAINT work_items_approved_doc_version_check CHECK (((approved_doc_version IS NULL) OR (approved_doc_version >= 1))),
    CONSTRAINT work_items_blocked_reason_check CHECK (((blocked_reason IS NULL) OR (char_length(blocked_reason) <= 2000))),
    CONSTRAINT work_items_check CHECK (((parent_id IS NULL) OR (parent_id <> id))),
    CONSTRAINT work_items_check1 CHECK (((type <> 'epic'::text) OR ((parent_id IS NULL) AND (epic_id IS NULL) AND (feature_id IS NULL)))),
    CONSTRAINT work_items_check2 CHECK (((type <> 'feature'::text) OR (feature_id IS NULL))),
    CONSTRAINT work_items_check3 CHECK (((type <> 'subtask'::text) OR (parent_id IS NOT NULL))),
    CONSTRAINT work_items_check4 CHECK ((((type = ANY (ARRAY['epic'::text, 'feature'::text])) AND (status = ANY (ARRAY['todo'::text, 'in_progress'::text, 'done'::text, 'wont_do'::text]))) OR ((type <> ALL (ARRAY['epic'::text, 'feature'::text])) AND (status = ANY (ARRAY['todo'::text, 'in_progress'::text, 'in_review'::text, 'testing'::text, 'done'::text, 'blocked'::text, 'reopened'::text, 'wont_do'::text]))))),
    CONSTRAINT work_items_check5 CHECK (((type = 'bug'::text) OR ((severity IS NULL) AND (NOT is_regression)))),
    CONSTRAINT work_items_check6 CHECK (((type = 'feature'::text) OR ((doc_wiki_page_id IS NULL) AND (doc_status IS NULL) AND (approved_doc_version IS NULL)))),
    CONSTRAINT work_items_check7 CHECK (((doc_wiki_page_id IS NULL) = (doc_status IS NULL))),
    CONSTRAINT work_items_check8 CHECK (((status = 'blocked'::text) OR (blocked_reason IS NULL))),
    CONSTRAINT work_items_description_check CHECK (((description IS NULL) OR (char_length(description) <= 50000))),
    CONSTRAINT work_items_doc_status_check CHECK ((doc_status = ANY (ARRAY['draft'::text, 'in_review'::text, 'changes_requested'::text, 'approved'::text]))),
    CONSTRAINT work_items_estimate_minutes_check CHECK (((estimate_minutes IS NULL) OR ((estimate_minutes >= 1) AND (estimate_minutes <= 100000)))),
    CONSTRAINT work_items_key_num_check CHECK ((key_num > 0)),
    CONSTRAINT work_items_priority_check CHECK ((priority = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'urgent'::text]))),
    CONSTRAINT work_items_reopen_count_check CHECK ((reopen_count >= 0)),
    CONSTRAINT work_items_severity_check CHECK ((severity = ANY (ARRAY['S1'::text, 'S2'::text, 'S3'::text, 'S4'::text]))),
    CONSTRAINT work_items_title_check CHECK (((char_length(btrim(title)) >= 1) AND (char_length(btrim(title)) <= 300))),
    CONSTRAINT work_items_type_check CHECK ((type = ANY (ARRAY['epic'::text, 'feature'::text, 'task'::text, 'bug'::text, 'subtask'::text]))),
    CONSTRAINT work_items_version_check CHECK ((version >= 1))
);


--
-- Name: workspace_ai_cache; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workspace_ai_cache (
    project_id uuid NOT NULL,
    kind text NOT NULL,
    cache_key text NOT NULL,
    output jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT workspace_ai_cache_cache_key_check CHECK (((char_length(cache_key) >= 1) AND (char_length(cache_key) <= 200))),
    CONSTRAINT workspace_ai_cache_kind_check CHECK ((kind = ANY (ARRAY['requirement_gaps'::text, 'epic_suggestions'::text, 'task_breakdown'::text, 'change_impact'::text, 'weekly_summary'::text, 'late_explanation'::text, 'release_notes'::text])))
);


--
-- Name: workspace_digests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workspace_digests (
    project_id uuid NOT NULL,
    digest_date date NOT NULL,
    health_color text NOT NULL,
    sent_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT workspace_digests_health_color_check CHECK ((health_color = ANY (ARRAY['green'::text, 'yellow'::text, 'red'::text])))
);


--
-- Name: workspace_projects; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workspace_projects (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    title text NOT NULL,
    requirement text NOT NULL,
    requirement_version integer DEFAULT 1 NOT NULL,
    skills text[] DEFAULT '{}'::text[] NOT NULL,
    team_size_min integer NOT NULL,
    team_size_max integer NOT NULL,
    interest_deadline timestamp with time zone,
    key_prefix text NOT NULL,
    project_status text DEFAULT 'draft'::text NOT NULL,
    brief_status text DEFAULT 'raw'::text NOT NULL,
    share_token text NOT NULL,
    share_token_rotated_at timestamp with time zone,
    accepting_interests boolean DEFAULT true NOT NULL,
    brief_wiki_page_id uuid,
    team_id uuid,
    gitlab_enabled boolean DEFAULT true NOT NULL,
    sprints_enabled boolean DEFAULT false NOT NULL,
    wip_limit integer DEFAULT 3 NOT NULL,
    item_seq integer DEFAULT 0 NOT NULL,
    health_thresholds jsonb DEFAULT '{"s1_open_hours": 24, "blocked_red_pct": 25, "forecast_red_pct": 20, "review_wait_days": 3, "reopen_yellow_pct": 20}'::jsonb NOT NULL,
    activated_at timestamp with time zone,
    brief_agreed_at timestamp with time zone,
    completed_at timestamp with time zone,
    feedback_closes_at timestamp with time zone,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    cohort_id uuid,
    CONSTRAINT workspace_projects_brief_status_check CHECK ((brief_status = ANY (ARRAY['raw'::text, 'clarifying'::text, 'agreed'::text]))),
    CONSTRAINT workspace_projects_check CHECK ((team_size_min <= team_size_max)),
    CONSTRAINT workspace_projects_check1 CHECK ((((project_status = 'completed'::text) = (completed_at IS NOT NULL)) OR (project_status = 'archived'::text))),
    CONSTRAINT workspace_projects_item_seq_check CHECK ((item_seq >= 0)),
    CONSTRAINT workspace_projects_key_prefix_check CHECK ((key_prefix ~ '^[A-Z]{2,6}$'::text)),
    CONSTRAINT workspace_projects_project_status_check CHECK ((project_status = ANY (ARRAY['draft'::text, 'recruiting'::text, 'active'::text, 'paused'::text, 'completed'::text, 'cancelled'::text, 'archived'::text]))),
    CONSTRAINT workspace_projects_requirement_check CHECK (((char_length(requirement) >= 50) AND (char_length(requirement) <= 20000))),
    CONSTRAINT workspace_projects_requirement_version_check CHECK ((requirement_version >= 1)),
    CONSTRAINT workspace_projects_share_token_check CHECK (((char_length(share_token) >= 22) AND (char_length(share_token) <= 64))),
    CONSTRAINT workspace_projects_skills_check CHECK ((cardinality(skills) <= 30)),
    CONSTRAINT workspace_projects_team_size_max_check CHECK ((team_size_max <= 50)),
    CONSTRAINT workspace_projects_team_size_min_check CHECK ((team_size_min >= 2)),
    CONSTRAINT workspace_projects_title_check CHECK (((char_length(btrim(title)) >= 3) AND (char_length(btrim(title)) <= 200))),
    CONSTRAINT workspace_projects_wip_limit_check CHECK (((wip_limit >= 1) AND (wip_limit <= 50)))
);


--
-- Name: xp_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.xp_events (
    id bigint NOT NULL,
    user_id uuid NOT NULL,
    org_id uuid,
    batch_id uuid,
    course_id uuid,
    xp_amount integer NOT NULL,
    reason text NOT NULL,
    reference_id uuid,
    reference_type text,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE xp_events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.xp_events IS 'Partitioning candidate — monthly range on created_at.';


--
-- Name: xp_events_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.xp_events ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.xp_events_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: auth_events id; Type: DEFAULT; Schema: public; Owner: -
--

ALTER TABLE ONLY public.auth_events ALTER COLUMN id SET DEFAULT nextval('public.auth_events_id_seq'::regclass);


